#!/usr/bin/env bash
#
# kauth setup wizard: walks an operator through everything the app reads from
# backend/.env plus the one-off ops steps (cleanup schedule, first staff
# member). Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

banner "kauth setup"

# gen_hex emits 32 random bytes as 64 hex characters — enough entropy for the
# JWT/cookie secrets (production enforces >=32 chars) and for ENCRYPTION_KEY
# (config.ts decodes it and requires >=32 bytes, AES-256).
gen_hex() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex 32
  else
    LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom | head -c 64 || true
  fi
}

# ensure_secret KEY generates a fresh value when missing, or offers a
# regeneration choice on re-runs. Values are never printed to the screen.
ensure_secret() {
  local key="$1" fresh
  local current; current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    if confirm "$key already set in $ENV_FILE — regenerate it?"; then
      fresh="$(gen_hex)"
      printf -v "$key" '%s' "$fresh"
      write_env "$key" "$fresh"
    else
      printf -v "$key" '%s' "$current"
      note "kept existing $key"
    fi
  else
    fresh="$(gen_hex)"
    printf -v "$key" '%s' "$fresh"
    write_env "$key" "$fresh"
  fi
}

# ── Stage 1: runtime secrets ───────────────────────────────────────────────
stage "Runtime secrets"
say "Generating three secrets straight into $ENV_FILE. They are never"
say "displayed; re-running lets you keep or regenerate each one."
ensure_secret JWT_SECRET
ensure_secret COOKIE_SECRET
ensure_secret ENCRYPTION_KEY
pause

# ── Stage 2: database ──────────────────────────────────────────────────────
stage "Database"
say "kauth needs PostgreSQL 17. For local dev the docker compose file maps"
say "it to port 5433:  docker compose up -d db"
DEFAULT_DB='postgresql://postgres:postgres@localhost:5433/kauth?schema=public'
ask DATABASE_URL "Paste the Postgres connection string [$DEFAULT_DB]:"
[[ -z "$DATABASE_URL" ]] && DATABASE_URL="$DEFAULT_DB"
write_env DATABASE_URL "$DATABASE_URL"

# ── Stage 3: redis ─────────────────────────────────────────────────────────
stage "Redis"
say "The shared rate-limit store counts against Redis (ADR 0005); without"
say "it the app degrades to per-instance memory counting. Local dev:"
say "docker compose up -d redis"
ask_secret REDIS_URL "Redis URL [redis://localhost:6379]:"
[[ -z "$REDIS_URL" ]] && REDIS_URL="redis://localhost:6379"
write_env REDIS_URL "$REDIS_URL"
pause

# ── Stage 4: public URLs ───────────────────────────────────────────────────
stage "Public URLs & proxy"
say "The auth server's own public origin builds OAuth callback URLs and"
say "email links. No trailing slash."
ask APP_URL "Auth server origin [http://localhost:6767]:"
[[ -z "$APP_URL" ]] && APP_URL="http://localhost:6767"
APP_URL="${APP_URL%/}"
write_env APP_URL "$APP_URL"
ask FRONTEND_URL "Browser app origin [http://localhost:5173]:"
[[ -z "$FRONTEND_URL" ]] && FRONTEND_URL="http://localhost:5173"
FRONTEND_URL="${FRONTEND_URL%/}"
write_env FRONTEND_URL "$FRONTEND_URL"
say "Register these two redirect URIs with the OAuth providers in the next"
say "stages:"
note "Google  → $APP_URL/oauth/google/callback"
note "GitHub  → $APP_URL/oauth/github/callback"
ask TRUST_PROXY "Reverse proxies in front of the app, or false [false]:"
[[ -z "$TRUST_PROXY" ]] && TRUST_PROXY="false"
write_env TRUST_PROXY "$TRUST_PROXY"
if [[ "$TRUST_PROXY" != "false" ]]; then
  warn "TRUST_PROXY must equal the real proxy count — a wrong value corrupts"
  warn "req.ip, which the audit log and IP rate limiters depend on."
fi
say "Trusted origins default to the two URLs above; list extras (comma-"
say "separated) only if other origins make state-changing browser requests."
ask TRUSTED_ORIGINS "Extra trusted origins [none]:"
if [[ -n "$TRUSTED_ORIGINS" ]]; then
  write_env TRUSTED_ORIGINS "$TRUSTED_ORIGINS"
else
  note "left unset — defaults apply"
fi
pause

# ── Stage 5: google oauth app ──────────────────────────────────────────────
stage "Google sign-in (optional)"
if ! confirm "Configure Google sign-in now?"; then
  SKIPPED+=("Google sign-in (no GOOGLE_CLIENT_ID/SECRET in $ENV_FILE; the provider stays off)")
  warn "skipped — Google login stays disabled until the env pair is set"
else
  open_url "https://console.cloud.google.com/apis/credentials"
  step "Pick (or create) the Google Cloud project for this kauth instance."
  step "If prompted, configure the OAuth consent screen first (External is"
  step "fine for development; add yourself as a test user)."
  step "Create Credentials → OAuth client ID → Application type: Web application."
  step "Under Authorized redirect URIs, add exactly:"
  note "    $APP_URL/oauth/google/callback"
  step "Create, then copy the Client ID (visible) and Client Secret."
  ask GOOGLE_CLIENT_ID "Paste the Google Client ID:"
  write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
  ask_secret GOOGLE_CLIENT_SECRET "Paste the Google Client Secret:"
  write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
  say "Callback URL to keep on file: $APP_URL/oauth/google/callback"
fi
pause

# ── Stage 6: github oauth app ──────────────────────────────────────────────
stage "GitHub sign-in (optional)"
if ! confirm "Configure GitHub sign-in now?"; then
  SKIPPED+=("GitHub sign-in (no GITHUB_CLIENT_ID/SECRET in $ENV_FILE; the provider stays off)")
  warn "skipped — GitHub login stays disabled until the env pair is set"
else
  open_url "https://github.com/settings/developers"
  step "OAuth Apps → New OAuth App."
  step "Application name: anything recognizable (e.g. 'kauth dev')."
  step "Homepage URL: $FRONTEND_URL"
  step "Authorization callback URL — exactly:"
  note "    $APP_URL/oauth/github/callback"
  step "Register, then 'Generate a new client secret' and copy both values."
  ask GITHUB_CLIENT_ID "Paste the GitHub Client ID:"
  write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
  ask_secret GITHUB_CLIENT_SECRET "Paste the GitHub Client Secret:"
  write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"
  say "Callback URL to keep on file: $APP_URL/oauth/github/callback"
fi
pause

# ── Stage 7: mail transport ────────────────────────────────────────────────
stage "Mail transport"
say "kauth ships no mail transport. The default prints verification links and"
say "reset tokens to stdout — fine for local dev, never for production, which"
say "refuses to boot without a real one configured."
say "MAILER_MODULE names your own module (resolved from the working"
say "directory) exporting a Mailer as its default export or a named 'mailer'"
say "export. Leave blank to keep the dev console transport."
ask MAILER_MODULE "Path to your mailer module [blank = console transport]:"
if [[ -n "$MAILER_MODULE" ]]; then
  write_env MAILER_MODULE "$MAILER_MODULE"
else
  note "left unset — the dev console transport stays active (development only)"
fi
pause

# ── Stage 8: email verification flag ───────────────────────────────────────
stage "Email verification policy"
say "REQUIRE_EMAIL_VERIFICATION=true refuses credential logins until the"
say "address is confirmed. Turning it on without working email delivery locks"
say "every user out."
if [[ -n "$MAILER_MODULE" ]]; then
  say "A mail transport is configured, so this is safe to enable."
  ask REQUIRE_EMAIL_VERIFICATION "Require verified email for login? [false]:"
  [[ -z "$REQUIRE_EMAIL_VERIFICATION" ]] && REQUIRE_EMAIL_VERIFICATION="false"
  write_env REQUIRE_EMAIL_VERIFICATION "$REQUIRE_EMAIL_VERIFICATION"
else
  write_env REQUIRE_EMAIL_VERIFICATION "false"
  note "forced to false — no mail transport is configured (see previous stage)"
  SKIPPED+=("Email verification — revisit REQUIRE_EMAIL_VERIFICATION once MAILER_MODULE is set")
fi
pause

# ── Stage 9: cleanup job schedule ──────────────────────────────────────────
stage "Cleanup job schedule"
say "scripts/cleanup.ts deletes sessions and audit events past retention."
say "It is a plain script — nothing schedules it for you. Daily is typical:"
note ""
note "  crontab:"
note "    17 3 * * * cd /path/to/kauth/backend && bun run cleanup >> cleanup.log 2>&1"
note ""
note "  or a systemd timer (OnCalendar=daily) running:"
note "    bun run cleanup"
note ""
say "Tuning lives in CLEANUP_RETENTION_DAYS (default 30) and"
say "AUDIT_RETENTION_DAYS (default 365); see docs/adr/0004."
SKIPPED+=("Cleanup scheduling — install the cron line/systemd timer shown above")
pause

# ── Stage 10: first staff member ───────────────────────────────────────────
stage "First platform staff member"
say "Nothing grants ADMIN over HTTP until one staff member exists. The"
say "bootstrap promotes an already-registered platform-project user:"
note "  bun scripts/promoteStaff.ts --email <address>"
say "(register them first via POST /register with the x-project-id header;"
say "the reserved platform Project id comes from the seed/docs)."
STAFF_EMAIL=""
ask STAFF_EMAIL "Platform user email to promote (blank to skip):"
if [[ -n "$STAFF_EMAIL" ]]; then
  if confirm "Run the promotion now against DATABASE_URL?"; then
    if ( cd "$(dirname "$0")/.." && bun scripts/promoteStaff.ts --email "$STAFF_EMAIL" ); then
      note "promotion attempted — check the output above"
    else
      SKIPPED+=("Staff promotion failed (DB up? user registered?) — rerun:")
      SKIPPED+=("  bun scripts/promoteStaff.ts --email $STAFF_EMAIL")
      warn "could not run it now; do it manually once the server + DB are up"
    fi
  else
    SKIPPED+=("Staff promotion — run later: bun scripts/promoteStaff.ts --email $STAFF_EMAIL")
  fi
fi

finish
